const items = $input.all();
return items.map((item, idx) => {
  const raw = item.json.body ?? item.json ?? {};
  const caseId = String(raw.case_id || `IFD-AUTO-${Date.now()}-${idx}`);
  const workflowType = raw.workflow_type === 'menu_audit' ? 'menu_audit' : 'dispute_fraud';
  const riskScore = Math.max(0, Math.min(1, Number(raw.risk_score ?? 0.5)));
  const mlAnomalyFlag = Boolean(raw.ml_anomaly_flag ?? (riskScore >= 0.7));
  const financialImpactBrl = Number(raw.financial_impact_brl ?? 0);

  let slaPriority = 'STANDARD_P2';
  let targetSlaSeconds = 900;
  let estimatedHoursSaved = 0.18;
  if (riskScore >= 0.75) {
    slaPriority = 'CRITICAL_P0';
    targetSlaSeconds = 30;
    estimatedHoursSaved = 0.45;
  } else if (riskScore >= 0.40) {
    slaPriority = 'HIGH_P1';
    targetSlaSeconds = 300;
    estimatedHoursSaved = 0.28;
  }

  const seed = `${caseId}:${workflowType}:${riskScore.toFixed(4)}:${financialImpactBrl.toFixed(2)}`;
  let hashNum = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    hashNum ^= seed.charCodeAt(i);
    hashNum = Math.imul(hashNum, 16777619);
  }
  const auditHash = 'SHA256-SIM-' + (hashNum >>> 0).toString(16).padStart(8, '0').toUpperCase();

  return {
    json: {
      case_id: caseId,
      workflow_type: workflowType,
      risk_score: Number(riskScore.toFixed(4)),
      ml_anomaly_flag: mlAnomalyFlag,
      vision_summary: String(raw.vision_summary || 'Multimodal inspection completed.'),
      rag_policy_clause: String(raw.rag_policy_clause || 'POL-GEN-1.0: Standard Marketplace Governance.'),
      recommended_action: String(raw.recommended_action || 'EVALUATE_CASE'),
      financial_impact_brl: Number(financialImpactBrl.toFixed(2)),
      audit_hash: auditHash,
      sla_priority: slaPriority,
      target_sla_seconds: targetSlaSeconds,
      estimated_hours_saved: estimatedHoursSaved,
      execution_timestamp: new Date().toISOString()
    }
  };
});

return $input.all().map((item) => {
  const d = item.json;
  const isMenu = d.workflow_type === 'menu_audit';
  return {
    json: {
      ...d,
      routed_branch: 'CRITICAL_RISK_AUTO_BLOCK',
      incident_protocol: `INC-P0-${d.case_id}-${d.audit_hash.slice(-6)}`,
      actions_executed: isMenu
        ? [
            'QUARANTINE_COMPLIANCE_VIOLATION_SKU',
            'BLOCK_PUBLICATION_ON_CATALOG_ENGINE',
            'OPEN_TRUST_AND_SAFETY_INCIDENT_TICKET',
            'NOTIFY_PARTNER_COMPLIANCE_WEBHOOK'
          ]
        : [
            'BLOCK_AUTOMATED_REFUND_PAYOUT',
            'FLAG_ACCOUNT_FOR_SYBIL_RING_REVIEW',
            'OPEN_TRUST_AND_SAFETY_INCIDENT_TICKET',
            'FREEZE_DISPUTE_CREDIT_LEDGER'
          ],
      fraud_savings_brl: Number((d.financial_impact_brl * 0.96).toFixed(2)),
      operational_cost_saved_brl: Number((d.estimated_hours_saved * 62.0).toFixed(2)),
      resolution_status: 'AUTO_BLOCKED_P0'
    }
  };
});

