return $input.all().map((item) => {
  const d = item.json;
  const totalBenefitBrl = Number(((d.fraud_savings_brl || 0) + (d.operational_cost_saved_brl || 0)).toFixed(2));
  return {
    json: {
      status: 'success',
      orchestrator: 'iFood Sentinel & MenuOps — Multi-Agent Action Orchestrator',
      n8n_protocol_id: d.incident_protocol,
      case_id: d.case_id,
      workflow_type: d.workflow_type,
      routed_branch: d.routed_branch,
      sla_priority: d.sla_priority,
      resolution_status: d.resolution_status,
      actions_executed: d.actions_executed,
      roi_metrics: {
        risk_score: d.risk_score,
        ml_anomaly_flag: d.ml_anomaly_flag,
        financial_exposure_brl: d.financial_impact_brl,
        fraud_or_gmv_impact_brl: d.fraud_savings_brl,
        operational_cost_saved_brl: d.operational_cost_saved_brl,
        total_estimated_benefit_brl: totalBenefitBrl,
