        target_sla_seconds: d.target_sla_seconds
      },
      evidence_context: {
        vision_summary: d.vision_summary,
        rag_policy_clause: d.rag_policy_clause,
        recommended_action: d.recommended_action,
        audit_hash: d.audit_hash,
        execution_timestamp: d.execution_timestamp
      }
    }
  };
});
